files.content:
*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  display: grid;
  place-items: center;
  min-width: 500px;
  min-height: 100vh;
  margin: 0;
  padding: 40px;
  overflow: hidden;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
  background-color: #fff;
  background-image: url(https://code.s3.yandex.net/web-code/images/dotted.svg);
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  border: 0;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
}

.search-form__label {
  min-width: 300px;
}

.character {
  position: absolute;
  width: 200px;
  transition: translate 0.5s ease-in-out;
}

.character:first-of-type {
  bottom: -20px;
  left: 40px;
  translate: 0 100%;
}

.character:nth-of-type(2) {
  right: 40px;
  bottom: 0;
  translate: calc(100% + 40px) 0;
}
.search-form:focus-within ~ .character {
  translate: 0 0;
}
